const elements={inputJson:document.getElementById('inputJson'),outputJson:document.getElementById('outputJson'),formatBtn:document.getElementById('formatBtn'),minifyBtn:document.getElementById('minifyBtn'),validateBtn:document.getElementById('validateBtn'),toXmlBtn:document.getElementById('toXmlBtn'),toCsvBtn:document.getElementById('toCsvBtn'),clearBtn:document.getElementById('clearBtn'),downloadBtn:document.getElementById('downloadBtn'),themeToggle:document.getElementById('themeToggle'),uploadZone:document.getElementById('uploadZone'),fileInput:document.getElementById('fileInput'),messageContainer:document.getElementById('messageContainer'),inputCount:document.getElementById('inputCount'),outputCount:document.getElementById('outputCount'),fullscreenBtn:document.getElementById('fullscreenBtn'),fullscreenModal:document.getElementById('fullscreenModal'),closeFullscreen:document.getElementById('closeFullscreen'),fullscreenOutput:document.getElementById('fullscreenOutput'),errorIndicator:document.getElementById('errorIndicator'),errorDetails:document.getElementById('errorDetails'),currentYear:document.getElementById('currentYear'),hamburgerBtn:document.getElementById('hamburgerBtn'),navMenu:document.getElementById('navMenu')};const API_BASE=window.location.origin;let currentOutputType='json';let currentOperation='formatted';function setCurrentYear(){if(elements.currentYear){elements.currentYear.textContent=new Date().getFullYear();}}
function initTheme(){const savedTheme=localStorage.getItem('theme')||'light';document.documentElement.setAttribute('data-theme',savedTheme);}
function openFullscreen(){const output=elements.outputJson.value.trim();if(!output){showMessage('error','No Output','There is no output to display in fullscreen.');return;}
elements.fullscreenOutput.textContent=output;elements.fullscreenModal.classList.add('active');document.body.style.overflow='hidden';}
function closeFullscreenModal(){elements.fullscreenModal.classList.remove('active');document.body.style.overflow='';}
function copyFullscreenContent(){const output=elements.fullscreenOutput.textContent;if(!output){showMessage('error','No Content','There is no content to copy.');return;}
navigator.clipboard.writeText(output).then(()=>{showMessage('success','Copied!','Content copied to clipboard.');}).catch(()=>{showMessage('error','Copy Failed','Failed to copy to clipboard.');});}
document.addEventListener('keydown',(e)=>{if(e.key==='Escape'&&elements.fullscreenModal.classList.contains('active')){closeFullscreenModal();}});elements.fullscreenModal?.addEventListener('click',(e)=>{if(e.target===elements.fullscreenModal){closeFullscreenModal();}});function highlightError(errorMessage){const lineMatch=errorMessage.match(/line (\d+)/i);const columnMatch=errorMessage.match(/column (\d+)/i);if(lineMatch||columnMatch){const line=lineMatch?parseInt(lineMatch[1]):null;const column=columnMatch?parseInt(columnMatch[1]):null;if(elements.errorDetails){const locationText=line&&column?`Line ${line},Column ${column}`:line?`Line ${line}`:column?`Column ${column}`:'Unknown location';elements.errorDetails.querySelector('.error-location').textContent=locationText;elements.errorDetails.querySelector('.error-message').textContent=errorMessage;elements.errorDetails.style.display='flex';if(line&&elements.errorIndicator){const textarea=elements.inputJson;const lines=textarea.value.split('\n');const lineHeight=parseFloat(getComputedStyle(textarea).lineHeight)||20;const topPosition=(line-1)*lineHeight;elements.errorIndicator.style.top=`${topPosition}px`;elements.errorIndicator.style.height=`${lineHeight}px`;elements.errorIndicator.style.display='block';const scrollPosition=Math.max(0,topPosition-(textarea.offsetHeight/2));textarea.scrollTop=scrollPosition;}}}else{if(elements.errorDetails){elements.errorDetails.querySelector('.error-location').textContent='JSON Error';elements.errorDetails.querySelector('.error-message').textContent=errorMessage;elements.errorDetails.style.display='flex';}}}
function clearErrorHighlight(){if(elements.errorIndicator){elements.errorIndicator.style.display='none';}
if(elements.errorDetails){elements.errorDetails.style.display='none';}}
function showMessage(type,title,text){const message=document.createElement('div');message.className=`message ${type}`;const icon=type==='success'?'✓':type==='error'?'✗':'ℹ';message.innerHTML=`<div class="message-icon">${icon}</div><div class="message-content"><div class="message-title">${title}</div><div class="message-text">${text}</div></div>`;elements.messageContainer.appendChild(message);setTimeout(()=>{message.style.animation='slideOut 0.3s ease-in-out';setTimeout(()=>message.remove(),300);},5000);}
function updateCharCount(){const inputLength=elements.inputJson.value.length;const outputLength=elements.outputJson.value.length;if(elements.inputCount){elements.inputCount.textContent=`${inputLength.toLocaleString()}characters`;}
if(elements.outputCount){elements.outputCount.textContent=`${outputLength.toLocaleString()}characters`;}
const charCount=document.getElementById('charCount');if(charCount){charCount.textContent=`${inputLength.toLocaleString()}characters`;}}
async function makeApiCall(endpoint,data,loadingBtn){try{clearErrorHighlight();loadingBtn.classList.add('loading');const response=await fetch(`${API_BASE}/api/${endpoint}/`,{method:'POST',headers:{'Content-Type':'application/json',},body:JSON.stringify({data})});const result=await response.json();loadingBtn.classList.remove('loading');return result;}catch(error){loadingBtn.classList.remove('loading');throw error;}}
async function formatJson(){const input=elements.inputJson.value.trim();if(!input){showMessage('error','No Input','Please enter JSON data to format.');return;}
try{const result=await makeApiCall('format',input,elements.formatBtn);if(result.success){elements.outputJson.value=result.formatted;currentOutputType='json';currentOperation='formatted';updateCharCount();showMessage('success','Formatted Successfully','Your JSON has been formatted with proper indentation.');}else{highlightError(result.error);showMessage('error','Format Failed',result.error);}}catch(error){showMessage('error','Error',`Failed to format JSON:${error.message}`);}}
async function minifyJson(){const input=elements.inputJson.value.trim();if(!input){showMessage('error','No Input','Please enter JSON data to minify.');return;}
try{const result=await makeApiCall('minify',input,elements.minifyBtn);if(result.success){elements.outputJson.value=result.minified;currentOutputType='json';currentOperation='minified';updateCharCount();showMessage('success','Minified Successfully','Your JSON has been compressed by removing whitespace.');}else{highlightError(result.error);showMessage('error','Minify Failed',result.error);}}catch(error){showMessage('error','Error',`Failed to minify JSON:${error.message}`);}}
async function validateJson(){const input=elements.inputJson.value.trim();if(!input){showMessage('error','No Input','Please enter JSON data to validate.');return;}
try{const result=await makeApiCall('validate',input,elements.validateBtn);if(result.valid){elements.outputJson.value=JSON.stringify(result.data,null,2);currentOutputType='json';currentOperation='validated';updateCharCount();clearErrorHighlight();showMessage('success','Valid JSON',result.message);}else{highlightError(result.message);showMessage('error','Invalid JSON',result.message);}}catch(error){showMessage('error','Validation Error',`Failed to validate JSON:${error.message}`);}}
async function convertToXml(){const input=elements.inputJson.value.trim();if(!input){showMessage('error','No Input','Please enter JSON data to convert to XML.');return;}
try{const result=await makeApiCall('convert/xml',input,elements.toXmlBtn);if(result.success){elements.outputJson.value=result.xml;currentOutputType='xml';currentOperation='converted';updateCharCount();showMessage('success','Converted to XML','Your JSON has been successfully converted to XML format.');}else{highlightError(result.error);showMessage('error','Conversion Failed',result.error);}}catch(error){showMessage('error','Error',`Failed to convert to XML:${error.message}`);}}
async function convertToCsv(){const input=elements.inputJson.value.trim();if(!input){showMessage('error','No Input','Please enter JSON data to convert to CSV.');return;}
try{const result=await makeApiCall('convert/csv',input,elements.toCsvBtn);if(result.success){elements.outputJson.value=result.csv;currentOutputType='csv';currentOperation='converted';updateCharCount();showMessage('success','Converted to CSV','Your JSON has been successfully converted to CSV format.');}else{highlightError(result.error);showMessage('error','Conversion Failed',result.error);}}catch(error){showMessage('error','Error',`Failed to convert to CSV:${error.message}`);}}
async function base64Encode(){const input=elements.inputJson.value.trim();if(!input){showMessage('error','No Input','Please enter text data to encode.');return;}
try{const tempBtn=elements.formatBtn;tempBtn.classList.add('loading');const response=await fetch(`${API_BASE}/api/base64/encode/`,{method:'POST',headers:{'Content-Type':'application/json',},body:JSON.stringify({data:input})});const result=await response.json();tempBtn.classList.remove('loading');if(result.success){elements.outputJson.value=result.encoded;currentOutputType='txt';currentOperation='encoded';updateCharCount();showMessage('success','Encoded Successfully','Your text has been encoded to Base64.');}else{showMessage('error','Encoding Failed',result.error);}}catch(error){elements.formatBtn.classList.remove('loading');showMessage('error','Error',`Failed to encode:${error.message}`);}}
async function base64Decode(){const input=elements.inputJson.value.trim();if(!input){showMessage('error','No Input','Please enter Base64 data to decode.');return;}
try{const tempBtn=elements.minifyBtn;tempBtn.classList.add('loading');const response=await fetch(`${API_BASE}/api/base64/decode/`,{method:'POST',headers:{'Content-Type':'application/json',},body:JSON.stringify({data:input})});const result=await response.json();tempBtn.classList.remove('loading');if(result.success){elements.outputJson.value=result.decoded;currentOutputType='txt';currentOperation='decoded';updateCharCount();showMessage('success','Decoded Successfully','Your Base64 data has been decoded to text.');}else{showMessage('error','Decoding Failed',result.error);}}catch(error){elements.minifyBtn.classList.remove('loading');showMessage('error','Error',`Failed to decode:${error.message}`);}}
function clearInputs(){elements.inputJson.value='';elements.outputJson.value='';currentOutputType='json';currentOperation='formatted';clearErrorHighlight();updateCharCount();showMessage('info','Cleared','All inputs and outputs have been cleared.');}
function downloadOutput(){const output=elements.outputJson.value.trim();if(!output){showMessage('error','No Output','There is no output to download.');return;}
const extensions={json:'json',xml:'xml',csv:'csv',txt:'txt'};const mimeTypes={json:'application/json;charset=utf-8',xml:'application/xml;charset=utf-8',csv:'text/csv;charset=utf-8',txt:'text/plain;charset=utf-8'};const filenames={formatted:`formatted.${extensions[currentOutputType]}`,minified:`minified.${extensions[currentOutputType]}`,validated:`validated.${extensions[currentOutputType]}`,converted:`converted.${extensions[currentOutputType]}`,encoded:`encoded.${extensions[currentOutputType]}`,decoded:`decoded.${extensions[currentOutputType]}`};const extension=extensions[currentOutputType]||'txt';const mimeType=mimeTypes[currentOutputType]||'text/plain;charset=utf-8';const filename=filenames[currentOperation]||`output.${extension}`;const blob=new Blob([output],{type:mimeType});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);showMessage('success','Downloaded',`File saved as ${filename}`);}
function handleFileUpload(file){if(!file)return;if(!file.name.endsWith('.json')){showMessage('error','Invalid File','Please upload a JSON file.');return;}
const reader=new FileReader();reader.onload=(e)=>{elements.inputJson.value=e.target.result;clearErrorHighlight();updateCharCount();showMessage('success','File Loaded',`${file.name}has been loaded successfully.`);};reader.onerror=()=>{showMessage('error','Read Error','Failed to read the file.');};reader.readAsText(file,'UTF-8');}
function toggleMobileMenu(){if(elements.hamburgerBtn&&elements.navMenu){elements.hamburgerBtn.classList.toggle('active');elements.navMenu.classList.toggle('active');}}
function closeMobileMenu(){if(elements.hamburgerBtn&&elements.navMenu){elements.hamburgerBtn.classList.remove('active');elements.navMenu.classList.remove('active');}}
function setupNavMenuActions(){const navItems=document.querySelectorAll('.dropdown-item[data-action]');navItems.forEach(item=>{item.addEventListener('click',(e)=>{e.preventDefault();const action=e.currentTarget.dataset.action;closeMobileMenu();switch(action){case'format':formatJson();break;case'minify':minifyJson();break;case'validate':validateJson();break;case'toXml':convertToXml();break;case'toCsv':convertToCsv();break;case'base64Encode':base64Encode();break;case'base64Decode':base64Decode();break;}});});const comingSoonItems=document.querySelectorAll('.dropdown-item.coming-soon');comingSoonItems.forEach(item=>{item.addEventListener('click',(e)=>{e.preventDefault();closeMobileMenu();showMessage('info','Coming Soon','This feature will be available in a future update.');});});const navLinks=document.querySelectorAll('.nav-link');navLinks.forEach(link=>{link.addEventListener('click',function(e){if(window.innerWidth<=1024){e.preventDefault();const parent=this.parentElement;parent.classList.toggle('open');}});});}
elements.formatBtn.addEventListener('click',formatJson);elements.minifyBtn.addEventListener('click',minifyJson);elements.validateBtn.addEventListener('click',validateJson);elements.toXmlBtn.addEventListener('click',convertToXml);elements.toCsvBtn.addEventListener('click',convertToCsv);elements.clearBtn.addEventListener('click',clearInputs);elements.downloadBtn.addEventListener('click',downloadOutput);elements.fullscreenBtn?.addEventListener('click',openFullscreen);elements.closeFullscreen?.addEventListener('click',closeFullscreenModal);const copyFullscreenBtn=document.getElementById('copyFullscreen');if(copyFullscreenBtn){copyFullscreenBtn.addEventListener('click',copyFullscreenContent);}
elements.inputJson.addEventListener('input',()=>{updateCharCount();clearErrorHighlight();});elements.uploadZone.addEventListener('click',()=>elements.fileInput.click());elements.fileInput.addEventListener('change',(e)=>{if(e.target.files.length>0){handleFileUpload(e.target.files[0]);}});elements.uploadZone.addEventListener('dragover',(e)=>{e.preventDefault();elements.uploadZone.classList.add('dragover');});elements.uploadZone.addEventListener('dragleave',()=>{elements.uploadZone.classList.remove('dragover');});elements.uploadZone.addEventListener('drop',(e)=>{e.preventDefault();elements.uploadZone.classList.remove('dragover');if(e.dataTransfer.files.length>0){handleFileUpload(e.dataTransfer.files[0]);}});document.addEventListener('keydown',(e)=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();formatJson();}
if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();clearInputs();}
if(e.key==='F11'){e.preventDefault();if(elements.outputJson.value.trim()){openFullscreen();}}});function init(){initTheme();updateCharCount();setCurrentYear();setupNavMenuActions();showMessage('info','Welcome!','Paste your JSON or drag & drop a file to get started.');}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}